package io.tornado.optimization;
import io.tornado.persistence.*;import org.slf4j.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.*;import java.util.concurrent.atomic.AtomicBoolean;
@Component public class ProfileResearchJobs{private static final Logger log=LoggerFactory.getLogger(ProfileResearchJobs.class);private final AppSettingsRepository settings;private final StrategyHorizonProfileRepository profiles;private final ProfileResearchService research;private final AtomicBoolean running=new AtomicBoolean();public ProfileResearchJobs(AppSettingsRepository s,StrategyHorizonProfileRepository p,ProfileResearchService r){settings=s;profiles=p;research=r;}
 @Scheduled(initialDelay=300000,fixedDelay=3600000)public void refreshOldestGlobalProfile(){AppSettings configuration=settings.findById(1).orElse(null);if(configuration==null||!configuration.isAutomaticProfileResearchEnabled()||!running.compareAndSet(false,true))return;try{Instant cutoff=Instant.now().minus(Duration.ofHours(configuration.getProfileRefreshIntervalHours()));var profile=profiles.findByActiveTrueOrderByPredictionHorizonSecondsAscStrategyCodeAsc().stream().filter(p->p.getProfileScope()==ProfileScope.GLOBAL&&p.getSelectedAt().isBefore(cutoff)).min(java.util.Comparator.comparing(StrategyHorizonProfile::getSelectedAt)).orElse(null);if(profile!=null)research.research(ProfileScope.GLOBAL,null,profile.getStrategyCode(),profile.getPredictionHorizonSeconds(),null,Instant.now());}catch(Exception e){log.warn("Scheduled profile research failed independently: {}",e.getMessage());}finally{running.set(false);}}
}
